inp={(0,0),(0,1),(1,1),(1,2),(2,0),(2,1)}; out={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def dihedral(s):
 for rot in range(4):
  t={(r,c) for r,c in s}
  for _ in range(rot): t={(c,-r) for r,c in t}
  for flip in [False,True]:
   u={(r,-c if flip else c) for r,c in t}; mr=min(r for r,c in u); mc=min(c for r,c in u); u={(r-mr,c-mc) for r,c in u}
   yield rot,flip,u
[(r,f,s) for r,f,s in dihedral(inp) if s==out]
